using XamlG.Syntax;
namespace XamlG.CSharp;
public sealed record XamlSourceMapping(TextSpan GeneratedSpan, TextSpan SourceSpan, string SourcePath);

using System.Collections.Immutable;
using XamlG.Syntax;
namespace XamlG.CSharp;
public sealed record XamlEmissionResult(string HintName, string Source, string FactoryTypeName, string? BuildMethodName, string PopulateMethodName, ImmutableArray<XamlDiagnostic> Diagnostics, ImmutableArray<XamlSourceMapping> SourceMappings)
{
    public bool Success => !Diagnostics.Any(d => d.Severity == XamlSeverity.Error) && Source.Length != 0;
}

using System.Text;
namespace XamlG.CSharp;
internal sealed class CSharpWriter
{
    private readonly StringBuilder _text = new();
    public int Indent { get; set; }
    public int Position => _text.Length;
    public void Line(string text = "")
    {
        if (text.Length != 0 && !text.StartsWith("#", StringComparison.Ordinal)) _text.Append(' ', Indent * 4);
        _text.Append(text).Append('\n');
    }
    public void Open(string header) { Line(header); Line("{"); Indent++; }
    public void Close(string suffix = "") { Indent--; Line("}" + suffix); }
    public override string ToString() => _text.ToString();
}

using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using XamlG.Roslyn;
namespace XamlG.CSharp;
internal static class CSharpNames
{
    public const string Context = "global::XamlG.Runtime.XamlRuntimeContext";
    public const string Session = "global::XamlG.Runtime.XamlRuntimeSession";
    public const string Provider = "global::System.IServiceProvider";
    public const string InvariantCulture = "global::System.Globalization.CultureInfo.InvariantCulture";
    public static string Identifier(string value) => "@" + value;
    public static string Literal(string value) => SymbolDisplay.FormatLiteral(value, true);
    public static string StableId(string value)
    {
        using var hash = SHA256.Create(); var bytes = hash.ComputeHash(Encoding.UTF8.GetBytes(value));
        return string.Concat(bytes.Take(12).Select(b => b.ToString("x2", CultureInfo.InvariantCulture)));
    }
    public static string Method(IMethodSymbol method) => Identifier(method.Name) + (method.IsGenericMethod ? "<" + string.Join(", ", method.TypeArguments.Select(t => t.CSharpName())) + ">" : string.Empty);
    public static string Constant(object? value) => value switch
    {
        null => "null", string text => Literal(text), char character => SymbolDisplay.FormatLiteral(character, true), bool boolean => boolean ? "true" : "false",
        byte number => "(byte)" + number.ToString(CultureInfo.InvariantCulture), sbyte number => "(sbyte)" + number.ToString(CultureInfo.InvariantCulture),
        short number => "(short)" + number.ToString(CultureInfo.InvariantCulture), ushort number => "(ushort)" + number.ToString(CultureInfo.InvariantCulture),
        int number => number == int.MinValue ? "global::System.Int32.MinValue" : number.ToString(CultureInfo.InvariantCulture),
        uint number => number.ToString(CultureInfo.InvariantCulture) + "U",
        long number => number == long.MinValue ? "global::System.Int64.MinValue" : number.ToString(CultureInfo.InvariantCulture) + "L",
        ulong number => number.ToString(CultureInfo.InvariantCulture) + "UL",
        float number => float.IsNaN(number) ? "global::System.Single.NaN" : float.IsPositiveInfinity(number) ? "global::System.Single.PositiveInfinity" : float.IsNegativeInfinity(number) ? "global::System.Single.NegativeInfinity" : number.ToString("R", CultureInfo.InvariantCulture) + "F",
        double number => double.IsNaN(number) ? "global::System.Double.NaN" : double.IsPositiveInfinity(number) ? "global::System.Double.PositiveInfinity" : double.IsNegativeInfinity(number) ? "global::System.Double.NegativeInfinity" : number.ToString("R", CultureInfo.InvariantCulture) + "D",
        decimal number => number.ToString(CultureInfo.InvariantCulture) + "M",
        _ => throw new ArgumentException("Only CLR scalar constants may reach the source emitter.", nameof(value))
    };
}

using System.Threading;
using Microsoft.CodeAnalysis;
using XamlG.Compiler;
using XamlG.Roslyn;
using XamlG.Syntax;
namespace XamlG.CSharp;
internal sealed class EmissionContext
{
    private int _temporary;
    private readonly Dictionary<ISymbol, string> _descriptors = new(SymbolEqualityComparer.Default);
    private readonly Dictionary<IMethodSymbol, string> _initSetters = new(SymbolEqualityComparer.Default);
    public EmissionContext(BoundDocument document, CancellationToken cancellation)
    { Document = document; Cancellation = cancellation; Diagnostics.AddRange(document.Diagnostics); Id = CSharpNames.StableId(document.Options.DocumentId ?? document.Syntax.Path); }
    public BoundDocument Document { get; }
    public string Id { get; }
    public CancellationToken Cancellation { get; }
    public CSharpWriter Writer { get; } = new();
    public List<XamlDiagnostic> Diagnostics { get; } = new();
    public List<XamlSourceMapping> Mappings { get; } = new();
    public string RootVariable { get; set; } = "__root";
    public string ServicesType => "__XamlGServices_" + Id;
    public string Temporary(string role) => "__" + role + _temporary++;
    public void Map(TextSpan span, Action emit)
    {
        Cancellation.ThrowIfCancellationRequested();
        if (Document.Options.EmitLineDirectives && Document.Syntax.Path.Length != 0)
        { var offset = Math.Min(span.Start, Document.Syntax.Text.Length); Writer.Line("#line " + (Document.Syntax.Lines.GetPosition(offset).Line + 1) + " " + CSharpNames.Literal(Document.Syntax.Path)); }
        var start = Writer.Position; emit(); Mappings.Add(new(new(start, Writer.Position - start), span, Document.Syntax.Path));
        if (Document.Options.EmitLineDirectives && Document.Syntax.Path.Length != 0) Writer.Line("#line default");
    }
    public string Descriptor(BoundMember member)
    {
        if (_descriptors.TryGetValue(member.Symbol, out var name)) return name;
        name = "__descriptor_" + Id + "_" + _descriptors.Count; _descriptors.Add(member.Symbol, name); return name;
    }
    public string InitSetter(IMethodSymbol method)
    {
        if (_initSetters.TryGetValue(method, out var name)) return name;
        name = "__init_" + Id + "_" + _initSetters.Count; _initSetters.Add(method, name); return name;
    }
    public void EmitMetadataHelpers()
    {
        foreach (var pair in _descriptors)
        {
            var type = pair.Key.ContainingType.CSharpName(); var name = CSharpNames.Literal(pair.Key.Name); string expression;
            if (pair.Key is IPropertySymbol) expression = "typeof(" + type + ").GetProperty(" + name + ", global::System.Reflection.BindingFlags.Public | global::System.Reflection.BindingFlags.NonPublic | global::System.Reflection.BindingFlags.Instance)";
            else if (pair.Key is IEventSymbol) expression = "typeof(" + type + ").GetEvent(" + name + ", global::System.Reflection.BindingFlags.Public | global::System.Reflection.BindingFlags.NonPublic | global::System.Reflection.BindingFlags.Instance)";
            else if (pair.Key is IMethodSymbol method) expression = "typeof(" + type + ").GetMethod(" + name + ", new global::System.Type[] { " + string.Join(", ", method.Parameters.Select(p => "typeof(" + p.Type.CSharpName() + ")")) + " })";
            else expression = "null";
            Writer.Line("private static readonly object? " + pair.Value + " = " + expression + ";");
        }
        foreach (var pair in _initSetters)
        {
            var method = pair.Key;
            Writer.Line("[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.Method, Name = " + CSharpNames.Literal(method.MetadataName) + ")]");
            Writer.Line("private static extern void " + pair.Value + "(" + (method.ContainingType.IsValueType ? "ref " : "") + method.ContainingType.CSharpName() + " target, " + method.Parameters[0].Type.CSharpName() + " value);");
        }
    }
    public void Error(string message, TextSpan span) => Diagnostics.Add(new("XG1200", message, span));
}

using XamlG.Compiler;
namespace XamlG.CSharp;
internal static class BoundTraversal
{
    public static IEnumerable<BoundObject> Objects(BoundObject root, bool includeDeferred = false)
    {
        yield return root;
        foreach (var expression in Expressions(root)) foreach (var child in Objects(expression, includeDeferred)) yield return child;
    }
    public static IEnumerable<BoundExpression> Expressions(BoundObject root)
    {
        foreach (var argument in root.Arguments) yield return argument;
        foreach (var assignment in root.Assignments)
            foreach (var expression in Expressions(assignment)) yield return expression;
    }
    public static IEnumerable<BoundExpression> Expressions(BoundAssignment assignment) => assignment switch
    {
        BoundSetAssignment s => new[] { s.Value }, BoundAddAssignment a => a.Arguments, BoundDynamicSetAssignment d => new[] { d.Value },
        BoundAdaptedSetAssignment a => new[] { a.Value }, BoundCallAssignment c => c.Arguments, _ => Array.Empty<BoundExpression>()
    };
    private static IEnumerable<BoundObject> Objects(BoundExpression expression, bool includeDeferred)
    {
        if (expression is BoundObjectExpression obj) { foreach (var child in Objects(obj.Object, includeDeferred)) yield return child; yield break; }
        if (expression is BoundMarkupExpression markup) { foreach (var child in Objects(markup.Extension, includeDeferred)) yield return child; yield break; }
        foreach (var child in Children(expression, includeDeferred)) foreach (var nested in Objects(child, includeDeferred)) yield return nested;
    }
    public static bool ContainsReference(BoundExpression expression) => expression is BoundReferenceExpression || Children(expression, false).Any(ContainsReference);
    public static IEnumerable<BoundExpression> Children(BoundExpression expression, bool includeDeferred) => expression switch
    {
        BoundCastExpression cast => new[] { cast.Value }, BoundArrayExpression array => array.Values, BoundNewExpression n => n.Arguments,
        BoundCallExpression c => c.Receiver == null ? c.Arguments : c.Arguments.Insert(0, c.Receiver),
        BoundDeferredExpression d when includeDeferred => new[] { d.Content },
        BoundObjectExpression o => Expressions(o.Object), BoundMarkupExpression m => Expressions(m.Extension), _ => Array.Empty<BoundExpression>()
    };
}

using System.Collections.Immutable;
using System.Threading;
using Microsoft.CodeAnalysis;
using XamlG.Compiler;
using XamlG.Roslyn;
namespace XamlG.CSharp;

/// <summary>Deterministically lowers bound operations to ordinary statically typed C#. It never reparses XAML at runtime.</summary>
public sealed class CSharpEmitter
{
    public XamlEmissionResult Emit(BoundDocument document, CancellationToken cancellationToken = default)
    {
        var context = new EmissionContext(document, cancellationToken); var writer = context.Writer;
        var typeName = document.ClassSymbol?.ToDisplayString() ?? document.Options.GeneratedNamespace + ".Document_" + context.Id;
        var build = document.ClassSymbol == null && document.Options.GenerateBuildMethod ? "Build" : null;
        var populate = "__XamlGPopulate_" + context.Id;
        if (!document.Success) return new(context.Id + ".xaml.g.cs", string.Empty, typeName, build, populate, context.Diagnostics.ToImmutableArray(), ImmutableArray<XamlSourceMapping>.Empty);
        writer.Line("// <auto-generated by XamlG />"); writer.Line("#nullable enable annotations"); writer.Line("#nullable disable warnings");
        var root = document.Root!;
        var namespaceName = document.ClassSymbol?.ContainingNamespace is { IsGlobalNamespace: false } ns ? ns.ToDisplayString() : document.ClassSymbol == null ? document.Options.GeneratedNamespace : string.Empty;
        if (namespaceName.Length != 0) writer.Open("namespace " + namespaceName);
        var containers = new Stack<INamedTypeSymbol>();
        for (var type = document.ClassSymbol; type != null; type = type.ContainingType) containers.Push(type);
        var nesting = containers.Count;
        if (containers.Count == 0) writer.Open("public static class Document_" + context.Id);
        else foreach (var type in containers)
        {
            var kind = type.IsRecord ? type.IsValueType ? "record struct " : "record class " : type.IsValueType ? "struct " : "class ";
            var parameters = type.Arity == 0 ? string.Empty : "<" + string.Join(", ", type.TypeParameters.Select(p => CSharpNames.Identifier(p.Name))) + ">";
            writer.Open("partial " + kind + CSharpNames.Identifier(type.Name) + parameters);
        }
        var flow = new ObjectEmitter(context);
        if (document.ClassSymbol != null && document.Options.GenerateNamedFields)
            foreach (var named in BoundTraversal.Objects(root).Where(n => n.Name != null && n.NameScopeId == root.NameScopeId))
                if (!document.ClassSymbol.GetMembers(named.Name!).Any()) writer.Line(named.FieldModifier + " " + named.Type.CSharpName() + " " + CSharpNames.Identifier(named.Name!) + " = default!;");
        if (build != null)
        {
            writer.Open("public static " + root.Type.CSharpName() + " Build(" + CSharpNames.Provider + "? __services = null)");
            flow.EmitContext("__context", "__services", "null");
            var value = flow.Emit(root, "__context", null, null); writer.Line("__context.Complete(" + value + ");"); writer.Line("return " + value + ";"); writer.Close();
        }
        writer.Open("public static void " + populate + "(" + root.Type.CSharpName() + " __root, " + CSharpNames.Provider + "? __services = null)");
        writer.Line("if (__root is null) throw new global::System.ArgumentNullException(nameof(__root));");
        flow.EmitContext("__context", "__services", "__root"); flow.Emit(root, "__context", "__root", null); writer.Line("__context.Complete(__root);"); writer.Close();
        if (document.ClassSymbol != null && document.Options.GenerateInitializeComponent && !document.ClassSymbol.GetMembers("InitializeComponent").Any())
        {
            writer.Line("private bool __xamlGInitialized_" + context.Id + ";");
            writer.Open("private void InitializeComponent()");
            writer.Line("if (__xamlGInitialized_" + context.Id + ") return;");
            writer.Line(populate + "(this);"); writer.Line("__xamlGInitialized_" + context.Id + " = true;"); writer.Close();
        }
        new ServiceContractEmitter(context).Emit(); context.EmitMetadataHelpers();
        if (nesting == 0) writer.Close(); else for (var i = 0; i < nesting; i++) writer.Close();
        if (namespaceName.Length != 0) writer.Close();
        return new(context.Id + ".xaml.g.cs", writer.ToString(), typeName, build, populate, context.Diagnostics.ToImmutableArray(), context.Mappings.ToImmutableArray());
    }
}
